import"chrome://resources/cr_elements/icons.html.js";import"//resources/cr_elements/cr_action_menu/cr_action_menu.js";import"//resources/cr_elements/cr_icon_button/cr_icon_button.js";import"//resources/cr_elements/icons.html.js";import{PolymerElement}from"chrome://resources/polymer/v3_0/polymer/polymer_bundled.min.js";import{getTemplate}from"./user_note_overview_row_menu.html.js";import{UserNotesApiProxyImpl}from"./user_notes_api_proxy.js";export class UserNoteOverviewRowMenuElement extends PolymerElement{constructor(){super(...arguments);this.userNotesApi_=UserNotesApiProxyImpl.getInstance()}static get is(){return"user-note-overview-row-menu"}static get template(){return getTemplate()}static get properties(){return{overview:Object}}onMenuButtonClick_(event){event.preventDefault();event.stopPropagation();this.$.menu.showAt(event.target)}onAddNoteClick_(event){event.preventDefault();event.stopPropagation();if(this.overview.isCurrentTab){this.dispatchEvent(new CustomEvent("current-tab-overview-selected",{bubbles:true,composed:true}))}else{this.userNotesApi_.noteOverviewSelected(this.overview.url,{middleButton:false,altKey:false,ctrlKey:false,metaKey:false,shiftKey:false})}this.dispatchEvent(new CustomEvent("start-note-creation",{bubbles:true,composed:true}));this.$.menu.close()}onOpenInNewTabClick_(event){event.preventDefault();event.stopPropagation();this.userNotesApi_.openInNewTab(this.overview.url);this.$.menu.close()}onOpenInNewWindowClick_(event){event.preventDefault();event.stopPropagation();this.userNotesApi_.openInNewWindow(this.overview.url);this.$.menu.close()}onOpenInIncognitoWindowClick_(event){event.preventDefault();event.stopPropagation();this.userNotesApi_.openInIncognitoWindow(this.overview.url);this.$.menu.close()}onDeleteClick_(event){event.preventDefault();event.stopPropagation();this.userNotesApi_.deleteNotesForUrl(this.overview.url);this.$.menu.close()}}customElements.define(UserNoteOverviewRowMenuElement.is,UserNoteOverviewRowMenuElement);